import { FormEvent, useEffect, useMemo, useRef, useState } from 'react';
import { ArrowLeft, ArrowRight, CalendarDays, Check, ChevronDown, Clock3, LogOut, Plus, ShieldCheck, Trophy, Users, Flag, Swords, Pencil, AlertTriangle, Trash2 } from 'lucide-react';

// Accept either the backend origin or an URL that already ends in /api.
// Also guard against duplicated prefixes from Vercel env/path configuration.
const API_ROOT=(import.meta.env.VITE_API_URL||'http://localhost:3000/api').replace(/\/+$/,'').replace(/(?:\/api)+$/i,'');
const API=`${API_ROOT}/api`;
const apiPath=(path:string)=>path.replace(/^(?:\/api)+(\/|$)/i,'$1');
const OPERATORS=['PLANILLERO','ADMIN_MESA'];
const ROUNDS=[['RONDA_32','Dieciseisavos','32 equipos · 16 partidos'],['OCTAVOS','Octavos de final','16 equipos · 8 partidos'],['CUARTOS','Cuartos de final','8 equipos · 4 partidos'],['SEMIFINAL','Semifinales','4 equipos · 2 partidos'],['TERCER_PUESTO','Tercer puesto','Partido por el tercer lugar'],['FINAL','Final','La final del torneo']] as const;
const ROUND_NAME:Record<string,string>=Object.fromEntries(ROUNDS.map(([key,name])=>[key,name]));
const STATE:Record<string,string>={POR_INICIAR:'PROGRAMADO',EN_JUEGO:'EN VIVO',DESCANSO:'PAUSA',FINALIZADO:'FINALIZADO',VALIDADO:'FINAL'};
type Team={id:string;nombre:string;eliminado?:boolean;delegado?:string|null};
type Incident={id:string;tipo:string;minuto:number;segundo:number;jugador?:string;equipo:string;creadoEn:string};
type Match={id:string;clockServerTime:number;clockReceivedAt:number;cancha:number;equipoLocal:string;equipoVisita:string;equipoLocalId:string|null;equipoVisitaId:string|null;fase:string;numeroEnFase:number;programadoPara:string|null;horaInicio:string|null;periodoActual:number;duracionPrimerTiempo:number;duracionSegundoTiempo:number;primerTiempoTranscurrido:number;golesLocal:number;golesVisita:number;penalesLocal:number;penalesVisita:number;penalesHechosLocal:number;penalesHechosVisita:number;ganadorId:string|null;ganador?:Team|null;esWO:boolean;woAusenteId:string|null;estado:string;clockSeconds:number;eventos:Incident[]};
type CourtImage={cancha:number;url:string|null};
async function api(path:string,token?:string,init:RequestInit={}){const headers=new Headers(init.headers);if(token)headers.set('Authorization',`Bearer ${token}`);if(init.body!==undefined&&init.body!==null&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');const response=await fetch(`${API}${apiPath(path)}`,{...init,headers});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).error||'No se pudo completar la solicitud');return response.status===204?null:response.json()}
const fmtTime=(seconds:number)=>`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;
const fmtDate=(value?:string|null)=>value?new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'Horario por confirmar';
function remainingSeconds(m:Match,elapsed=m.clockSeconds){const duration=m.periodoActual===2?m.duracionSegundoTiempo:m.duracionPrimerTiempo;const periodElapsed=m.periodoActual===2?Math.max(0,elapsed-m.primerTiempoTranscurrido):elapsed;return Math.max(0,duration-periodElapsed)}
function shootoutWinnerId(m:Match){if(Math.min(m.penalesHechosLocal,m.penalesHechosVisita)<3){if(m.penalesLocal>m.penalesVisita+Math.max(0,3-m.penalesHechosVisita))return m.equipoLocalId;if(m.penalesVisita>m.penalesLocal+Math.max(0,3-m.penalesHechosLocal))return m.equipoVisitaId}if(m.penalesHechosLocal===m.penalesHechosVisita&&m.penalesHechosLocal>=3&&m.penalesLocal!==m.penalesVisita)return m.penalesLocal>m.penalesVisita?m.equipoLocalId:m.equipoVisitaId;return null}
function phaseLabel(value:string){return ROUND_NAME[value]||value}
function bracketOrder<T extends Pick<Match,'numeroEnFase'|'programadoPara'|'cancha'|'id'>>(list:T[]){const values=list.map(match=>match.numeroEnFase),numbered=new Set(values).size===list.length&&values.every(value=>Number.isInteger(value)&&value>=1&&value<=list.length);return [...list].sort((a,b)=>numbered?a.numeroEnFase-b.numeroEnFase:(a.programadoPara?Date.parse(a.programadoPara):Number.MAX_SAFE_INTEGER)-(b.programadoPara?Date.parse(b.programadoPara):Number.MAX_SAFE_INTEGER)||a.cancha-b.cancha||a.id.localeCompare(b.id))}

export default function AppFinal(){
 const [route,setRoute]=useState(window.location.pathname),[matches,setMatches]=useState<Match[]>([]),[teams,setTeams]=useState<Team[]>([]),[courtImages,setCourtImages]=useState<CourtImage[]>([]),[apiError,setApiError]=useState('');
 const syncVersion=useRef(0);
 const [token,setToken]=useState(localStorage.getItem('mesa-token')||''),[user,setUser]=useState<any>(null),[loginError,setLoginError]=useState(''),[logging,setLogging]=useState(false);
 function navigate(path:string){window.history.pushState({},'',path);setRoute(path);window.scrollTo({top:0,behavior:'instant' as ScrollBehavior})}
 useEffect(()=>{const pop=()=>setRoute(window.location.pathname);window.addEventListener('popstate',pop);return()=>window.removeEventListener('popstate',pop)},[]);
 async function refresh(authToken=token){const version=++syncVersion.current;try{const [live,publicTeams,images,ops]=await Promise.all([api('/public/live'),api('/public/equipos'),api('/public/canchas'),authToken?api('/matches/operations',authToken):Promise.resolve(null)]);if(version!==syncVersion.current)return;const receivedAt=performance.now();setMatches((authToken?ops||[]:live.partidos||[]).map((match:Match)=>({...match,clockReceivedAt:receivedAt})));setTeams(publicTeams||[]);setCourtImages(images||[]);setApiError('')}catch(e:any){if(version===syncVersion.current){setApiError(e.message);setMatches([]);setTeams([])}}}
 async function syncMatches(authToken=token){const version=++syncVersion.current;try{const result=authToken?await api('/matches/operations',authToken):await api('/public/live');if(version!==syncVersion.current)return;const receivedAt=performance.now();setMatches((authToken?result||[]:result.partidos||[]).map((match:Match)=>({...match,clockReceivedAt:receivedAt})));setApiError('')}catch(e:any){if(version===syncVersion.current)setApiError(e.message)}}
 useEffect(()=>{void refresh(token);const source=new EventSource(`${API}/realtime/events`);let pending:number|undefined;const sync=()=>{if(pending)window.clearTimeout(pending);pending=window.setTimeout(()=>void syncMatches(token),10)};source.addEventListener('tournament:update',sync);source.onopen=()=>void syncMatches(token);const fallback=setInterval(()=>{if(document.visibilityState==='visible'&&source.readyState!==EventSource.OPEN)void syncMatches(token)},1500);const imageTimer=setInterval(async()=>{if(document.visibilityState!=='visible')return;try{setCourtImages(await api('/public/canchas'))}catch{}},30000);const visible=()=>{if(document.visibilityState==='visible')void syncMatches(token)};document.addEventListener('visibilitychange',visible);return()=>{source.close();if(pending)window.clearTimeout(pending);clearInterval(fallback);clearInterval(imageTimer);document.removeEventListener('visibilitychange',visible)}},[token]);
 useEffect(()=>{if(token)api('/me',token).then((me:any)=>setUser(me)).catch(()=>{localStorage.removeItem('mesa-token');setToken('');setUser(null)})},[token]);
 async function login(e:FormEvent<HTMLFormElement>){e.preventDefault();setLogging(true);setLoginError('');const fd=new FormData(e.currentTarget);try{const result=await api('/auth/login',undefined,{method:'POST',body:JSON.stringify({username:fd.get('username'),password:fd.get('password')})});localStorage.setItem('mesa-token',result.token);setToken(result.token);setUser(result.user);navigate('/panel')}catch(error:any){setLoginError(error.message)}finally{setLogging(false)}}
 function logout(){localStorage.removeItem('mesa-token');setToken('');setUser(null);navigate('/')}
 const courts=useMemo(()=>[1,2,3,4].map(n=>{const list=matches.filter(m=>m.cancha===n);return list.find(m=>m.estado==='EN_JUEGO')||list.find(m=>m.estado==='DESCANSO')||list.find(m=>m.estado==='POR_INICIAR')||list.find(m=>m.estado==='FINALIZADO')||list.find(m=>m.estado==='VALIDADO')}),[matches]);
 if(route==='/login')return <LoginPage onLogin={login} loading={logging} error={loginError} onBack={()=>navigate('/')}/>;
 if(route==='/panel')return user?<Operations user={user} token={token} matches={matches} teams={teams} courtImages={courtImages} refresh={()=>refresh(token)} syncMatches={()=>syncMatches(token)} onLogout={logout} onHome={()=>navigate('/')}/>:<LoginPage onLogin={login} loading={logging} error={loginError} onBack={()=>navigate('/')}/>;
 return <PublicHome matches={matches} courts={courts} teams={teams} courtImages={courtImages} apiError={apiError} onLogin={()=>navigate('/login')}/>;
}

